package ro.leo.visual;
import ro.leo.i18n.L;
import android.app.*;import android.content.*;import android.content.pm.*;import android.net.Uri;import android.os.*;import java.io.*;import java.util.*;
/** User-requested actions only. Built-in packages and essential Leo components cannot be removed here. */
public final class AppControlActivity extends LeoActivity {
 private String target;
 protected void onCreate(Bundle b){super.onCreate(b);target=getIntent().getStringExtra("package");if(target==null)apps();else show();}
 protected void onActivityResult(int r,int result,Intent data){super.onActivityResult(r,result,data);if(r==80)defaults();else if(target!=null)show();}
 private void apps(){begin(L.t("Centrul de aplicații"));root.addView(text(L.t("Se încarcă…"),16));footer("","",L.t("Înapoi"));back=null;final android.widget.LinearLayout loading=root;
  worker.execute(new Runnable(){public void run(){final ArrayList<PackageInfo> packages=new ArrayList<PackageInfo>(getPackageManager().getInstalledPackages(0));final HashMap<String,String> names=new HashMap<String,String>();for(PackageInfo p:packages)names.put(p.packageName,label(p));Collections.sort(packages,new Comparator<PackageInfo>(){public int compare(PackageInfo a,PackageInfo b){return names.get(a.packageName).compareToIgnoreCase(names.get(b.packageName));}});ui(new Runnable(){public void run(){if(root!=loading)return;ArrayList<String> labels=new ArrayList<String>();for(PackageInfo p:packages)labels.add(names.get(p.packageName)+"\n"+p.packageName);list(L.t("Centrul de aplicații"),labels,0,new Choice(){public void pick(int n){target=packages.get(n).packageName;show();}},L.t("Aplicații implicite"),new Runnable(){public void run(){defaults();}});}});}});}
 private String label(PackageInfo p){return p.applicationInfo.loadLabel(getPackageManager()).toString();}
 static boolean removable(PackageInfo p,String currentIme){return (p.applicationInfo.flags&(ApplicationInfo.FLAG_SYSTEM|ApplicationInfo.FLAG_UPDATED_SYSTEM_APP))==0&&!p.packageName.startsWith("ro.leo.")&&!p.packageName.equals("org.codeaurora.ims")&&!p.packageName.equals("com.android.phone")&&!p.packageName.equals(currentIme==null?"":currentIme.split("/")[0]);}
 private void show(){try{final PackageInfo p=getPackageManager().getPackageInfo(target,PackageManager.GET_PERMISSIONS);list(label(p),Arrays.asList(L.t("Spațiu ocupat"),L.t("Permisiuni"),L.t("Deschide aplicația"),L.t("Dezinstalează"),L.t("Informații Android")),0,new Choice(){public void pick(int n){if(n==0)storage(p);else if(n==1)permissions(p);else if(n==2){Intent open=getPackageManager().getLaunchIntentForPackage(target);if(open==null)notice(L.t("Aplicația nu are ecran de lansare"));else startActivity(open);}else if(n==3)uninstall(p);else try{startActivity(new Intent(android.provider.Settings.ACTION_APPLICATION_DETAILS_SETTINGS,Uri.parse("package:"+target)));}catch(RuntimeException e){notice(L.t("Pagina Android nu este disponibilă"));}}},"",null);back=new Runnable(){public void run(){target=null;apps();}};}catch(Exception e){target=null;apps();}}
 private void storage(final PackageInfo p){begin(L.t("Spațiu ocupat"));root.addView(text(L.t("Se încarcă…"),16));footer("","",L.t("Înapoi"));back=new Runnable(){public void run(){show();}};worker.execute(new Runnable(){public void run(){long apk=new File(p.applicationInfo.sourceDir).length();if(p.applicationInfo.splitSourceDirs!=null)for(String s:p.applicationInfo.splitSourceDirs)apk+=new File(s).length();String text=L.t("APK instalat · ")+android.text.format.Formatter.formatFileSize(AppControlActivity.this,apk);try{android.app.usage.StorageStats stats=((android.app.usage.StorageStatsManager)getSystemService(STORAGE_STATS_SERVICE)).queryStatsForPackage(android.os.storage.StorageManager.UUID_DEFAULT,p.packageName,android.os.Process.myUserHandle());text=L.t("Aplicație · ")+android.text.format.Formatter.formatFileSize(AppControlActivity.this,stats.getAppBytes())+"\n"+L.t("Date · ")+android.text.format.Formatter.formatFileSize(AppControlActivity.this,stats.getDataBytes())+"\nCache · "+android.text.format.Formatter.formatFileSize(AppControlActivity.this,stats.getCacheBytes());}catch(Exception e){Long data=directoryBytes(p.packageName,false),cache=directoryBytes(p.packageName,true);text+="\n"+(data==null?L.t("Date/cache: necesită acces la statistici de utilizare"):L.t("Date, inclusiv cache · ")+android.text.format.Formatter.formatFileSize(AppControlActivity.this,data)+(cache==null?"":"\nCache · "+android.text.format.Formatter.formatFileSize(AppControlActivity.this,cache)));}final String detail=text;ui(new Runnable(){public void run(){begin(L.t("Spațiu ocupat"));root.addView(text(detail,16));footer("","",L.t("Înapoi"));back=new Runnable(){public void run(){show();}};}});}});}
 private void permissions(final PackageInfo p){final ArrayList<String> ids=new ArrayList<String>(),labels=new ArrayList<String>();if(p.requestedPermissions!=null)for(String id:p.requestedPermissions)try{PermissionInfo info=getPackageManager().getPermissionInfo(id,0);if((info.protectionLevel&PermissionInfo.PROTECTION_MASK_BASE)!=PermissionInfo.PROTECTION_DANGEROUS)continue;ids.add(id);labels.add(info.loadLabel(getPackageManager())+"\n"+(getPackageManager().checkPermission(id,p.packageName)==PackageManager.PERMISSION_GRANTED?L.t("Permis"):L.t("Refuzat")));}catch(Exception ignored){}list(L.t("Permisiuni"),labels,0,new Choice(){public void pick(final int n){final String permission=ids.get(n);final boolean granted=getPackageManager().checkPermission(permission,p.packageName)==PackageManager.PERMISSION_GRANTED;if(p.applicationInfo.targetSdkVersion<23||p.packageName.startsWith("ro.leo.")||(p.applicationInfo.flags&ApplicationInfo.FLAG_SYSTEM)!=0){notice(L.t("Permisiune protejată · folosește informațiile Android"));return;}options(permission,new String[]{L.t("Anulează"),granted?L.t("Revocă permisiunea"):L.t("Acordă permisiunea")},new Choice(){public void pick(int yes){if(yes==1)command("pm "+(granted?"revoke":"grant")+" --user 0 "+p.packageName+" "+permission,new Runnable(){public void run(){try{permissions(getPackageManager().getPackageInfo(p.packageName,PackageManager.GET_PERMISSIONS));}catch(Exception e){show();}}});}});}},"",null);back=new Runnable(){public void run(){show();}};}
 private void uninstall(final PackageInfo p){if(!removable(p,android.provider.Settings.Secure.getString(getContentResolver(),"default_input_method"))||p.packageName.equals(android.provider.Telephony.Sms.getDefaultSmsPackage(this))||p.packageName.equals(((android.telecom.TelecomManager)getSystemService(TELECOM_SERVICE)).getDefaultDialerPackage())){notice(L.t("Aplicație protejată · dezinstalarea este blocată"));return;}options(L.t("Ștergi aplicația și datele ei?"),new String[]{L.t("Păstrează"),L.t("Dezinstalează")},new Choice(){public void pick(int n){if(n==1)command("pm uninstall --user 0 "+p.packageName,new Runnable(){public void run(){show();}});}});}
 private void command(final String command,final Runnable done){if(!command.matches("pm (uninstall --user 0 [A-Za-z0-9_.]+|(grant|revoke) --user 0 [A-Za-z0-9_.]+ [A-Za-z0-9_.]+)")){notice(L.t("Comandă invalidă"));return;}worker.execute(new Runnable(){public void run(){boolean ok=false;java.lang.Process process=null;try{process=new ProcessBuilder("/system/bin/leo-su","-c",command).redirectErrorStream(true).start();if(process.waitFor(8,java.util.concurrent.TimeUnit.SECONDS)){StringBuilder response=new StringBuilder();try(BufferedReader r=new BufferedReader(new InputStreamReader(process.getInputStream()))){String line;while((line=r.readLine())!=null&&response.length()<8192)response.append(line);}ok=process.exitValue()==0&&!response.toString().contains("Failure")&&!response.toString().contains("Exception");}}catch(Exception e){}finally{if(process!=null)process.destroy();}final boolean success=ok;ui(new Runnable(){public void run(){notice(success?L.t("Modificare aplicată"):L.t("Modificarea nu a fost permisă"));done.run();}});}});}
 private Long directoryBytes(String pkg,boolean cache){if(!pkg.matches("[A-Za-z0-9_.]+"))return null;java.lang.Process process=null;try{process=new ProcessBuilder("/system/bin/leo-su","-c","du -sk /data/user/0/"+pkg+(cache?"/cache":"")).redirectErrorStream(true).start();if(!process.waitFor(4,java.util.concurrent.TimeUnit.SECONDS)||process.exitValue()!=0)return null;try(BufferedReader r=new BufferedReader(new InputStreamReader(process.getInputStream()))){String line=r.readLine();if(line==null)return null;return Math.multiplyExact(Long.parseLong(line.trim().split("\\s+")[0]),1024L);}}catch(Exception e){return null;}finally{if(process!=null)process.destroy();}}
 private void defaults(){String sms=android.provider.Telephony.Sms.getDefaultSmsPackage(this),dialer=((android.telecom.TelecomManager)getSystemService(TELECOM_SERVICE)).getDefaultDialerPackage();list(L.t("Aplicații implicite"),Arrays.asList("SMS · "+(sms==null?"—":sms),L.t("Telefon · ")+(dialer==null?"—":dialer),L.t("Lansator / browser / alte roluri")),0,new Choice(){public void pick(int n){if(n<2)role(n==0);else try{startActivity(new Intent(android.provider.Settings.ACTION_MANAGE_DEFAULT_APPS_SETTINGS));}catch(RuntimeException e){notice(L.t("Configurarea implicitelor nu este disponibilă"));}}},"",null);back=new Runnable(){public void run(){apps();}};}
 private void role(final boolean sms){final LinkedHashMap<String,String> choices=new LinkedHashMap<String,String>();if(sms){for(ResolveInfo r:getPackageManager().queryBroadcastReceivers(new Intent(android.provider.Telephony.Sms.Intents.SMS_DELIVER_ACTION),0))if(r.activityInfo!=null&&r.activityInfo.exported)choices.put(r.activityInfo.packageName,r.loadLabel(getPackageManager()).toString());}else for(ResolveInfo r:getPackageManager().queryIntentActivities(new Intent(Intent.ACTION_DIAL,Uri.parse("tel:")),0))if(r.activityInfo!=null&&r.activityInfo.exported)choices.put(r.activityInfo.packageName,r.loadLabel(getPackageManager()).toString());final ArrayList<String> ids=new ArrayList<String>(choices.keySet());list(sms?L.t("Aplicație SMS implicită"):L.t("Telefon implicit"),new ArrayList<String>(choices.values()),0,new Choice(){public void pick(int n){try{Intent change=sms?new Intent(android.provider.Telephony.Sms.Intents.ACTION_CHANGE_DEFAULT).putExtra(android.provider.Telephony.Sms.Intents.EXTRA_PACKAGE_NAME,ids.get(n)):new Intent(android.telecom.TelecomManager.ACTION_CHANGE_DEFAULT_DIALER).putExtra(android.telecom.TelecomManager.EXTRA_CHANGE_DEFAULT_DIALER_PACKAGE_NAME,ids.get(n));startActivityForResult(change,80);}catch(RuntimeException e){notice(L.t("Configurarea implicitelor nu este disponibilă"));}}},"",null);back=new Runnable(){public void run(){defaults();}};}
}
